// sync behavior. Returns "" when HEAD is detached or unresolvable, so callers
// exercise the empty-stdin (no-op) case.
func (env *TestEnv) defaultPrePushStdin() string {
	branch := env.GetCurrentBranch()
	if branch == "" {
		return ""
