dest.warnIgnoredPushURLs(pushCtx)

// One shared deadline across the batch push and per-ref fetch+replay
// recovery — matching doPushRef. The git-refs batch path used to inherit
// the caller's ctx with no bound, so a stuck `git push` (401 + macOS
// osxkeychain, a remote that accepts then stalls) waited until the
// process died. Recovery already applied checkpointPushBudget per ref,
// but that never ran if the batch itself never returned.
pushCtx, cancel := context.WithTimeout(pushCtx, checkpointPushBudget)
defer cancel()

// Progress: pushing many refs over the network can take tens of seconds, so
// surface it (matching the v1 path's "[entire] Pushing ..." line) instead of
// leaving the user's git push apparently hung. Written to stderr, which git
// shows during the pre-push hook.
fmt.Fprintf(os.Stderr, "[entire] Pushing %d checkpoint ref(s) to %s...", len(existing), dest.display())
stop := startProgressDots(os.Stderr)

// Fast path: push all refs in one round-trip (fast-forward-only). If every
// ref was up to date or fast-forwarded, we're done.
batchErr := batchPushRefs(pushCtx, dest.target, existing)
if batchErr == nil {
	stop(" done")
	if removeErr := queue.Remove(existing); removeErr != nil {
		logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
			slog.String("error", removeErr.Error()))
	}
	return len(existing), nil
}
stop("")

// Budget expired on the batch: skip per-ref recovery. Recovery would
// inherit the expired deadline and fail instantly, but would still print
// "retrying N ref(s) individually" as if the remote had answered.
if pushCtx.Err() != nil {
	return 0, fmt.Errorf("push %d checkpoint refs: %w", len(existing), batchErr)
}

