	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
390→	t.Setenv("GIT_CONFIG_COUNT", "0")
}

func isGitConfigEnv(e string) bool {
	return strings.HasPrefix(e, "GIT_CONFIG_")

